void *child(void *arg) {
    printf("child\n");
    pthread_mutex_lock(&m);
    done = 1;                       // record the state change
    pthread_cond_signal(&c);        // wake the parent if it sleeps
    pthread_mutex_unlock(&m);
    return NULL;
}

int main(void) {
    pthread_t p;
